INSERT INTO portfolio_works (id, title, description, category_id, images) VALUES
                                                                              (1, 'Кухня из шпонированного дуба',
                                                                               E'Кухня для семьи, которая готовит каждый день: много закрытого хранения, ни одной лишней ручки и тёплый шпон дуба, который не боится влаги.\n\nСтолешницу сделали из кварца, фурнитуру поставили с доводчиками во всех ящиках. От замера до установки — 6 недель.',
                                                                               1, '["https://images.unsplash.com/photo-1556911220-bff31c812dba?auto=format&fit=crop&w=1600&q=80","https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80"]'::jsonb),
                                                                              (2, 'Гостиная с системой хранения из ореха',
                                                                               E'Задача была простая и сложная одновременно: вместить библиотеку на 400 книг и не превратить гостиную в склад.\n\nСделали стену хранения из ореха со скрытыми нишами и подсветкой. Диван — наш, по их эскизу посадки.',
                                                                               3, '["https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=1600&q=80","https://images.unsplash.com/photo-1567016432779-094069958ea5?auto=format&fit=crop&w=1600&q=80"]'::jsonb),
                                                                              (3, 'Спальня в тёплом минимализме',
                                                                               E'Спальня без визуального шума: кровать с мягким изголовем, прикроватные тумбы в цвет стен и шкаф, который растворяется в интерьере.\n\nВсе ткани подбирали вместе с заказчиками у нас в шоуруме образцов.',
                                                                               4, '["https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1600&q=80","https://images.unsplash.com/photo-1540518614846-7eded433c457?auto=format&fit=crop&w=1600&q=80"]'::jsonb),
                                                                              (4, 'Прихожая со скрытым хранением',
                                                                               E'Узкая прихожая, в которой нужно было спрятать всё: верхнюю одежду, обувь, самокат и лыжи.\n\nСделали шкафы до потолка с фасадами без ручей — открываются от нажатия. Внутри — продуманное наполнение под их сценарии.',
                                                                               2, '["https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=1600&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1600&q=80"]'::jsonb);

INSERT INTO portfolio_reviews (work_id, author_name, text, rating) VALUES
                                                                       (1, 'Анна и Сергей', 'Боялись, что срок поползёт, но ребята сдали даже раньше. Кухней пользуемся полгода — ни один фасад не повело, всё как в день установки.', 5),
                                                                       (1, 'Марина В.', 'Приехали на замер с образцами, посчитали смету на месте и она не изменилась ни на рубль. Это редкость.', 5),
                                                                       (2, 'Дмитрий', 'Долго согласовывали подсветку, но результат того стоил. Гостиная стала главной комнатой в доме.', 5),
                                                                       (3, 'Елена', 'Очень аккуратная работа и вежливые сборщики. Минус звезда только за то, что ждали чуть дольше из-за ткани — но нас предупреждали заранее.', 4),
                                                                       (4, 'Игорь', 'Шкафы съедают весь наш хаос. Отдельное спасибо за то, что предложили решения, о которых мы сами не подумали.', 5);

SELECT setval('portfolio_works_id_seq', (SELECT MAX(id) FROM portfolio_works));
